def word_frequency(text: str) -> dict[str, int]:
    import string
    frequency = {}
    words = text.translate(str.maketrans('', '', string.punctuation)).lower().split()
    for word in words:
        frequency[word] = frequency.get(word, 0) + 1
    return frequency
